template <typename scalar_t>
__device__ inline void scale_and_sub(
    typename ScalarType<scalar_t>::FragB& frag_b, scalar_t s, scalar_t zp)

num2num2(s);
  scalar_t2 zp2 = ScalarType<scalar_t>::num2num2(zp);
